                    }
                    {
                        \time 1/5
                        \times 4/5 {
                            c'4
                        }
                    }
                    {
                        \time 3/4
                        {
                            c'2.
                        }
                    }
                }

        Defined equal to copy of rhythm-maker.

        Returns new tuplet monad rhythm-maker.
        '''
        return type(self)()
